        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Change in pain intensity measured by Visual Analog Scale (VAS) at [time point]",
              "description": "Pain intensity will be assessed using the Visual Analog Scale (VAS), a 10 cm scale ranging from 0 (no pain) to 10 (worst imaginable pain). Participants will indicate their pain level by marking on the scale, and the score will be determined by measuring the distance in centimeters or millimeters.",
              "timeFrame": "Baseline and week 4"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Fatigue Level",
              "description": "Fatigue severity will be assessed using the Fatigue Severity Scale (FSS), a 9-item questionnaire evaluating fatigue over the past month. Each item is scored on a scale of 0 to 7, with higher scores indicating greater fatigue severity. The Turkish validity and reliability study was conducted by Armutlu et al. in 2007. A change of 0.45 points is considered clinically meaningful.",
              "timeFrame": "1 month"
            },
            {
              "measure": "Change in plasma beta-endorphin levels measured by ELISA at baseline and week 4",
              "description": "Plasma beta-endorphin levels will be measured using an ELISA method. Blood samples will be collected from participants in the intervention group before and after laughter yoga sessions at week 1 and week 4, and from the control group at week 1 and week 4. Samples will be centrifuged, and serum will be stored at -80°C until analysis. Beta-endorphin concentrations will be determined using a commercially available ELISA kit.",
              "timeFrame": "Baseline and week 4"
            }
          ]
        },
