              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "pH measurements",
              "description": "The pH will be estimated based on the calibration methods of quantification of exchange as a function of saturation time (QUEST)32 and its ratiometric analysis (QUESTRA) 33.",
              "timeFrame": "20 Minutes"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Healthy male or female non-MS control volunteers\n\nExclusion Criteria:\n\n* Medically unstable or with cardiac, pulmonary, hematological, renal, or hepatic dysfunction.\n* Current or past DSM-IV diagnosis of major depression, bipolar and psychotic disorders.\n* Contraindications for MRI, including\n* Intracranial clips\n* Metal implants\n* External metallic devices/objects/clips within 10mm of the head\n* Suspected or confirmed metal in the eyes (history of welding or similar activity)\n* Claustrophobia\n* Cardiac pacemaker or pacing wires\n* Pregnancy - Pregnancy tests will be offered to women of childbearing age at no cost to the subject\n* History of moderate to severe head injury, stroke, and seizures.\n* Alcoholism or drug dependency.\n* Renal or liver disease as this may cause concerns related to Gd-DTPA contrast agent.\n\n  * Allergy to the contrast agent Gadolinium\n  * Relapses or steroid therapy in patient at or in the month preceding the study\n  * Patients only",
          "healthyVolunteers": true,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "maximumAge": "65 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ],
          "studyPopulation": "Patients with relapse-remitting multiple sclerosis from NYU Langone Health and age-matched healthy volunteers recruiting using previous database of volunteers",
          "samplingMethod": "NON_PROBABILITY_SAMPLE"
        },
