        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Percentage of Participants Obtaining Successful Treatment",
              "description": "Success on the Investigator Global Assessment (IGA) scale is defined as clear or almost clear with an improvement of at least two grades from baseline. IGA scores range from 0-4:\n\n0=Clear\n\n1. Almost Clear\n2. Mild\n3. Moderate\n4. Severe",
              "timeFrame": "After 26 weeks treatment"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Time to Treatment Success",
              "description": "The time elapsed from the first dose to the time of treatment success, according to the Investigator's Global Assessment (IGA) scale. The total time of treatment was 26 weeks, although Covid-19 visit delays led to an extension of up to 2 weeks (28 weeks total) for some patients. Success on the Investigator Global Assessment (IGA) scale is defined as clear or almost clear with an improvement of at least two grades from baseline. IGA scores range from 0-4:\n\n0=Clear\n\n1. Almost Clear\n2. Mild\n3. Moderate\n4. Severe",
              "timeFrame": "From first dose to 26 weeks (± 2 weeks)"
            },
            {
              "measure": "Change From Baseline in Investigator's Global Assessment",
              "description": "The change in grading on the Investigator's Global Assessment (IGA) scale from baseline.\n\nIGA scores range from 0-4:\n\n0=Clear\n\n1. Almost Clear\n2. Mild\n3. Moderate\n4. Severe",
              "timeFrame": "At baseline and after 26 weeks treatment"
            },
            {
              "measure": "Change From Baseline in Facial Angiofibroma Severity Index (FASI)",
              "description": "The change in grading on the Facial Angiofibroma Severity Index (FASI) from baseline. FASI grades lesions according to their erythema, size and extent by summing the scores of each category. The final FASI scores range from (mild) 2-9 (severe).\n\nErythema Skin color 0 Light Red 1 Red 2 Dark Red/purple 3 Size None 0 Small (\\< 5mm) 1 Large (\\> 5mm) 2 Confluent 3 Extension \\<50 % cheek surface 2 \\>50% cheek surface 3",
              "timeFrame": "At baseline and after 26 weeks treatment"
            },
            {
              "measure": "Subjective (Participant or Parent/Caregiver) Percentage Change Rating Scale",
              "description": "Percentage change in facial angiofibroma since beginning treatment, as assessed by the participant or parent/caregiver. A large value indicates most improvement to facial angiofibroma (minimum=0, maximum=100). This was a single assessment time-point, where the participant or parent/caregiver estimated the percentage change in the facial angiofibroma lesion appearance from their perspective since baseline.",
              "timeFrame": "After 26 weeks treatment"
            },
            {
              "measure": "Objective (Clinician) Percentage Change Rating Scale",
              "description": "Percentage improvement in facial angiofibroma since beginning treatment, as assessed by the clinician. A large value indicates most improvement to facial angiofibroma (minimum=0, maximum=100). This was a single assessment time-point, where clinicians estimated the percentage change in the facial angiofibroma lesion appearance from their perspective since baseline.",
              "timeFrame": "After 26 weeks treatment"
            },
            {
              "measure": "Categorical Change in Facial Angiofibroma",
              "description": "Change in facial angiofibroma since beginning treatment on a 5-point scale, as assessed by the participant or parent/caregiver. This was a single assessment time-point, where the participant or parent/caregiver evaluated the change in the facial angiofibroma lesion appearance from their perspective since baseline.",
              "timeFrame": "After 26 weeks treatment"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n1. Male and female patients aged ≥ 6 years and ≤ 65 years on the day informed consent is obtained\n2. Patients diagnosed with TSC based on the clinical diagnostic criteria of International Tuberous Sclerosis Complex Consensus Conference 2012 and presenting visible facial angiofibroma\n3. An FA severity score of 2 or 3 on the IGA scale\n4. Patients or their legal representatives capable of understanding the explanation of the clinical trial and who give written informed consent for participation\n5. Patients or their legal representatives able to maintain patient diaries following the instructions of the investigator or sub-investigator\n\nExclusion Criteria:\n\n1. Patients who cannot carry out the treatment plan or follow-up assessment\n2. Patients with serious skin lesions such as erosions or ulcers\n3. Patients with known hypersensitivity to any component of the study product\n4. Patients who have received rapamycin/sirolimus, everolimus, or temsirolimus within 3 months of enrolment\n5. Patients who received laser therapy or surgical therapy within 6 months prior to trial enrolment\n6. Patients who participated in any other clinical trial within 3 months prior to the day of enrolment\n7. Patients judged unsuitable for this clinical trial by the investigator or sub-investigator\n8. Pregnant or lactating females\n9. Sexually active females of childbearing potential not using adequate contraception and sexually active males not using adequate contraception\n10. Patients with immune dysfunction or receiving any form of immunosuppression\n11. Patients with severe FA, with a score of 4 on the IGA scale\n12. Patients with an FA severity score of less than 2 on the IGA scale",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "6 Years",
          "maximumAge": "65 Years",
          "stdAges": [
            "CHILD",
            "ADULT",
            "OLDER_ADULT"
          ]
        },
