        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Percentage of Participants Obtaining Successful Treatment",
              "description": "Success on the Investigator Global Assessment (IGA) scale is defined as clear or almost clear with an improvement of at least two grades from baseline. IGA scores range from 0-4:\n\n0=Clear\n\n1. Almost Clear\n2. Mild\n3. Moderate\n4. Severe",
              "reportingStatus": "POSTED",
              "paramType": "COUNT_OF_PARTICIPANTS",
              "unitOfMeasure": "Participants",
              "timeFrame": "After 26 weeks treatment",
              "groups": [
                {
                  "id": "OG000",
                  "title": "0.5% Rapamycin Cream, Topical",
                  "description": "Rapamycin cream topical, 0.5% w/w, applied once daily before bed on affected area for 26 weeks\n\nrapamycin: Apply to the affected area once a day, approximately half an hour before retiring for bed in the evening, for 26 weeks"
                },
