          "briefTitle": "Efficacy of BIPAMS for Restless Legs Syndrome in Adults With Multiple Sclerosis: A Pilot Study",
          "officialTitle": "Efficacy of Project BIPAMS for Restless Legs Syndrome in Adults With Multiple Sclerosis: A Pilot Study"
        },
        "statusModule": {
