          "briefTitle": "Diagnostic and Prognostic Biomarkers for Childhood Bacterial Pneumonia",
          "officialTitle": "Diagnostic and Prognostic Biomarkers for Childhood Bacterial Pneumonia in Sub-Saharan Africa"
        },
        "statusModule": {
          "statusVerifiedDate": "2022-05",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
