            },
            {
              "measure": "Six-Month Progression-Free Survival (PFS) Rate as Assessed by BICR Per RECIST 1.1",
              "description": "Six-month PFS rate is defined as the percentage of participants who have survival without documented progressive disease (PD) per RECIST 1.1 by BICR or death due to any cause, whichever occurs first at 6 months after randomization. PD is defined as ≥20% increase in the sum of diameters of target lesions. In addition to the relative increase of 20%, the sum must also demonstrate an absolute increase of ≥5 mm. The appearance of one or more new lesions is also considered PD. PFS rate at 6 months as assessed by BICR is presented.",
              "timeFrame": "At 6 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Duration of Response (DOR) as Assessed by BICR Per RECIST 1.1",
              "description": "For participants who demonstrated a confirmed Complete Response (CR: disappearance of all target lesions) or Partial Response (PR: At least a 30% decrease in the sum of diameters of target lesions) per RECIST 1.1, DOR was defined as the time from first documented evidence of a CR or PR until progressive disease (PD) or death. DOR for participants who had not progressed or died at the time of analysis was to be censored at the date of their last tumor assessment. Per RECIST 1.1, PD was defined as at least a 20% increase in the sum of diameters of target lesions as well as an absolute increase of at least a 5 mm in the sum of diameters. The appearance of one or more new lesions was also considered PD. DOR assessments were based on blinded central imaging review with confirmation. The DOR as assessed using RECIST 1.1 for all participants who experienced a confirmed CR or PR is presented.",
              "timeFrame": "Up to approximately 43 months"
            },
            {
              "measure": "Progression-Free Survival (PFS) as Assessed by BICR Per RECIST 1.1",
              "description": "PFS is defined as the time from randomization to the first documented PD per RECIST 1.1 by BICR or death due to any cause, whichever occurs first. PD is defined as ≥20% increase in the sum of diameters of target lesions. In addition to the relative increase of 20%, the sum must also demonstrate an absolute increase of ≥5 mm. The appearance of one or more new lesions is also considered PD. PFS as assessed by BICR is presented.",
              "timeFrame": "Up to approximately 43 months"
            },
            {
              "measure": "Overall Survival (OS)",
              "description": "OS was defined as the time from randomization to death due to any cause. Participants without documented death at the time of the final analysis were to be censored at the date of the last follow-up. The OS for all participants is presented.",
              "timeFrame": "Up to approximately 43 months"
            },
            {
              "measure": "Mean Percent Change From Baseline in Tumor Size as Assessed by BICR Per RECIST 1.1",
              "description": "Tumor size change is defined as the best percent change from baseline in the sum of the diameters of the target lesions as assessed by BICR per RECIST 1.1. The mean best percent change from baseline in tumor size as assessed by BICR per RECIST 1.1 is presented.",
              "timeFrame": "Baseline and up to 43 months"
            },
            {
              "measure": "Number of Participants Who Experienced an Adverse Event (AE)",
              "description": "An AE is any untoward medical occurrence in a clinical study participant, temporally associated with the use of study intervention, whether or not considered related to the study intervention. An AE can therefore be any unfavorable and unintended sign (including an abnormal laboratory finding), symptom, or disease (new or exacerbated) temporally associated with the use of a study intervention. The number of participants who experience an AE is presented.",
              "timeFrame": "Up to approximately 43 months"
            },
            {
              "measure": "Number of Participants Who Discontinued Study Treatment Due to an AE",
              "description": "An AE is any untoward medical occurrence in a clinical study participant, temporally associated with the use of study intervention, whether or not considered related to the study intervention. An AE can therefore be any unfavorable and unintended sign (including an abnormal laboratory finding), symptom, or disease (new or exacerbated) temporally associated with the use of a study intervention. The number of participants who discontinue study treatment due to an AE is presented.",
              "timeFrame": "Up to approximately 22 months"
            },
            {
              "measure": "Change From Baseline in European Organization for Research and Treatment of Cancer Quality of Life Questionnaire-Core 30 (EORTC QLQ-C30) Global Health Status (Item 29) and Quality of Life (Item 30) Combined Score",
              "description": "The EORTC QLQ-C30 is a questionnaire to assess the overall quality of life of cancer patients. Participant responses to the questions \"How would you rate your overall health during the past week?\" and \"How would you rate your overall quality of life during the past week?\" are scored on a 7-point scale (1= Very poor to 7=Excellent). Using linear transformation, raw scores are standardized so that the total score ranges from 0 to 100 for the combined scores. A higher score indicates a better overall health status. The change from baseline in EORTC QLQ-C30 Items 29 and 30 combined score is presented.",
              "timeFrame": "Baseline, Week 19"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Has histologically or cytologically confirmed diagnosis of extensive-stage small cell lung cancer (ES-SCLC) in need of first-line therapy\n* Has ES-SCLC defined as Stage IV (T any, N any, M1a/b/c) by the American Joint Committee on Cancer, Eighth Edition\n* Male participants are eligible to participate if they agree to the following during the intervention period and for at least the time needed to eliminate each study intervention after the last dose of study intervention. The length of time required to continue contraception for each study intervention is as follows: Lenvatinib (7 days); Etoposide, Cisplatin, or Carboplatin (180 days) and Pembrolizumab, MK-4830, or (no contraception measures); refrain from donating sperm plus either be abstinent from heterosexual intercourse as their preferred and usual lifestyle (abstinent on a long-term and persistent basis) and agree to remain abstinent or must agree to use contraception per protocol unless confirmed to be azoospermic\n* A female participant is eligible to participate if she is not pregnant or breastfeeding, and at least one of the following conditions applies: Is not a woman/women of childbearing potential (WOCBP) or is a WOCBP and uses a contraceptive method that is highly effective with low user dependency or be abstinent from heterosexual intercourse as their preferred and usual lifestyle (abstinent on a long-term and persistent basis), during the intervention period and for at least the time needed to eliminate each study intervention after the last dose of study intervention and agrees not to donate eggs to others or freeze/store for her own use for the purpose of reproduction during this period. The length of time required to continue contraception for each study intervention is as follows: Lenvatinib (30 days), Etoposide, Cisplatin, or Carboplatin (180 days), and Pembrolizumab, MK-4830, or Boserolimab (120 days)\n* A WOCBP must have a negative highly sensitive pregnancy test (urine or serum as required by local regulations) within 24 hours (urine test) or 72 hours (serum test) before the first dose of study intervention\n* Abstains from breastfeeding during the study intervention period and for at least 120 days after study intervention\n* Has measurable disease per RECIST 1.1 as assessed by local site investigator/radiology and verified by blinded independent central review (BICR)\n* Submits an archival tumor tissue sample or newly obtained core, incisional, or excisional biopsy of a tumor lesion not previously irradiated where such sample exist\n* Has an Eastern Cooperative Oncology Group (ECOG) performance status of 0 or 1 assessed within 7 days before randomization\n* Has adequate organ function within 10 days before the first dose of study intervention\n* Has adequately controlled blood pressure (BP) with or without antihypertensive medications, defined as BP ≤150/90 mm Hg with no changes in antihypertensive medications within 1 week before randomization\n\nExclusion Criteria:\n\n* Has had major surgery within 3 weeks before first dose of study interventions\n* Has a preexisting ≥Grade 3 gastrointestinal or non-gastrointestinal fistula\n* Has urine protein ≥1 g/24 hours\n* Has a left ventricular ejection fraction (LVEF) below the institutional (or local laboratory) normal range, as determined by multiple gated acquisition (MUGA) or echocardiogram (ECHO)\n* Prolongation of QT interval with Fridericia's correction (QTcF) interval to \\>480 ms\n* Has clinically significant cardiovascular disease or major arterial thromboembolic event within 12 months before first dose of study intervention, including New York Heart Association Class III or IV congestive heart failure, unstable angina, myocardial infarction, cerebral vascular accident, or cardiac arrhythmia associated with hemodynamic instability\n* Has active hemoptysis within 3 weeks before the first dose of study intervention\n* Has gastrointestinal malabsorption or any other condition that might affect oral study intervention absorption\n* Has serious nonhealing wound, ulcer, or bone fracture within 28 days before first dose of study intervention\n* Has any major hemorrhage or venous thromboembolic events within 3 months before the first dose of study intervention. Participants with venous thrombosis diagnosed more than 3 months before the first dose of study intervention must be on stable doses of anticoagulants\n* Has a history of inflammatory bowel disease\n* Has a history of a gastrointestinal perforation within 6 months before the first dose of study intervention\n* Is considered a poor medical risk due to a serious, uncontrolled medical disorder or nonmalignant systemic disease\n* Has received prior therapy with an anti-programmed cell death 1 protein (anti-PD-1), anti-programmed cell death ligand 1 (anti-PD-L1), or anti programmed cell death ligand 2 (anti-PD-L2) agent or with an agent directed to another stimulatory or coinhibitory T-cell receptor\n* Has received prior treatment (chemotherapy, radiotherapy, or surgical resection) including investigational agents for SCLC\n* Is expected to require any other form of antineoplastic therapy for SCLC, including radiation therapy, while on study\n* Has received a live or live-attenuated vaccine within 30 days before the first dose of study intervention\n* Is currently participating in or has participated in a study of an investigational agent or has used an investigational device within 4 weeks before the first dose of study intervention\n* Has radiographic evidence of encasement or invasion of a major blood vessel, or of intratumoral cavitation. A participant that meets this exclusion criterion but is otherwise deemed eligible for the study may be randomized across the specific intervention groups.\n* Has symptomatic ascites, pleural effusion, or pericardial effusion. A participant who is clinically stable following treatment for these conditions is eligible\n* Has a diagnosis of immunodeficiency or is receiving chronic systemic steroid therapy (in dosing exceeding 10 mg daily of prednisone equivalent) or any other form of immunosuppressive therapy within 7 days prior the first dose of study intervention\n* Has a known additional malignancy that is progressing or has required active treatment within the past 3 years\n* Has known active central nervous system (CNS) metastases and/or carcinomatous meningitis. Participants with brain metastases may participate only if they satisfy all of the following: a) Completed treatment at least 14 days before the first dose of study intervention b) Have no evidence of new or enlarging brain metastases confirmed by posttreatment repeat brain imaging performed at least 4 weeks after pretreatment brain imaging, and c) Are neurologically stable without the need for steroids for at least 7 days before the first dose of study intervention as per local site assessment. Participants with untreated brain metastases will be allowed if they are asymptomatic, the investigator determines there is no immediate CNS-specific treatment required, there is no significant surrounding edema, and the brain metastases are of 5 mm or less in size and 3 or fewer in number\n* Has a history of severe hypersensitivity reaction to any study intervention and/or any of its excipients\n* Has an active autoimmune disease that has required systemic treatment in past 2 years\n* Has a history of (noninfectious) pneumonitis/interstitial lung disease that required steroids or has current pneumonitis/interstitial lung disease\n* Has a known history of, or active, neurologic paraneoplastic syndrome\n* Has an active infection requiring systemic therapy\n* Has a known history of human immunodeficiency virus (HIV) infection and/or Hepatitis B virus infection or an active Hepatitis C infection\n* Has a history or current evidence of any condition, therapy, laboratory abnormality, or other circumstance that might confound the results of the study, interfere with the participant's participation for the full duration of the study, such that it is not in the best interest of the participant to participate, in the opinion of the treating investigator\n* Has a known psychiatric or substance abuse disorder that would interfere with the participant's ability to cooperate with the requirements of the study\n* Has had an allogenic tissue/solid organ transplant",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
