[{"role": "assistant", "content": "", "tool_calls": [{"id": "call_2knh6liq", "type": "function", "function": {"name": "clinicaltrialsgov-mcp-server_clinicaltrials_list_studies", "arguments": "{"query":{"cond":"galactosialidosis"},"filter":{"overallStatus":["COMPLETED"]},"sort":["StartDate"],"pageSize":1}"}}]}, {"role": "tool", "content": [{"type": "text", "text": "{
