          "primaryOutcomes": [
            {
              "measure": "Mean, median and standard deviation of age distribution of patients with galactosialidosis.",
              "description": "The clinical and demographic data will be tabulated and analyzed for age distribution and disease manifestations with a goal of defining eligibility criteria for future therapeutic protocols.",
              "timeFrame": "At enrollment"
            }
          ],
          "secondaryOutcomes": [
