            {
              "type": "PRIMARY",
              "title": "Number of Participants With Dose-Limiting Toxicities (DLT)",
              "description": "Dose-limiting toxicity (DLT) will be defined as any one of the following: Any grade ≥ 3 hematologic toxicity or grade ≥ 3 non-hematologic toxicity that is possibly, probably, or definitely related to study drug, except transient (≤ 48 hour) grade 3 fatigue, local reactions, flu-like symptoms, fever, headache, and laboratory abnormalities that are not associated with organ pathology. Also any ≥ grade 2 allergic and ≥ grade 2 autoimmune reaction(s) (except endocrine-related immune toxicity) will be defined as a DLT. Any grade 3 autoimmune endocrine-related toxicity that has not resolved clinically within 7 days of initiating therapy will also be defined as a DLT. Generalized erythroderma or macular or papular rash lasting less than 7 days and not associated with desquamation will not be DLTs.",
              "reportingStatus": "POSTED",
              "paramType": "COUNT_OF_PARTICIPANTS",
              "unitOfMeasure": "Participants",
              "timeFrame": "28 days following the first injection of vaccine.",
              "groups": [
                {
