          "briefTitle": "Study To Examine Toxicity Of Allogeneic Stem Cell Transplantation For Relapsed Or Therapy Refractory Ewings Sarcoma",
          "officialTitle": "A Phase I Study to Examine the Toxicity of Allogeneneic Stem Cell Transplantation for Relapsed or Therapy Refractory Ewings",
          "acronym": "Ewing/Allo"
        },
        "statusModule": {
          "statusVerifiedDate": "2017-05",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
