        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Treatment Plan A",
              "type": "ACTIVE_COMPARATOR",
              "description": "Rabbit anti-thymocyte globulin (ATG) will be given only to unrelated donor transplant recipients at a dose of 3 mg/kg/day I.V. Equine ATG at a dose of 30mg/kg/day may be substituted in the event of severe allergic reaction to the rabbit ATG. Rabbit ATG is only used with recipients of unrelated donor marrow or peripheral blood transplants. Busulfan (BU) will be given at a dose of 0.8 mg/kg IV q 6 hrs. BU doses will be modified based upon pharmacokinetics data to maintain steady state levels of 600-900 ng/dl. Seizure prophylaxis with levetiracetam should begin prior to the 1st dose of BU and stoped 24 hrs after the last dose of BU. Melphalan will be given at a dose of 60 mg/m2 I.V. over 15-20 min per Pediatric SCT Standards of Practice Manual.",
              "interventionNames": [
                "Drug: Rabbit anti-thymocyte globulin",
                "Drug: Busulfan",
