        "descriptionModule": {
          "briefSummary": "This is a study to determine whether a combination of low dose lacosamide and levetiracetam is more effective than high dose levetiracetam in patients who have failed low dose levetiracetam."
        },
        "conditionsModule": {
          "conditions": [
            "Epilepsy"
          ],
