        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Lacosamide + Low-Dose Levetiracetam",
              "type": "EXPERIMENTAL",
              "description": "Participants received lacosamide 50 mg twice a day for one week followed by 100 mg twice daily added to low dose levetiracetam ≤1500 mg/day (polytherapy) for 6 months in patients with breakthrough seizures on low-dose levetiracetam.",
              "interventionNames": [
                "Drug: lacosamide",
                "Drug: levetiracetam"
              ]
            },
            {
              "label": "Control Group (High-Dose Levetiracetam)",
              "type": "OTHER",
              "description": "Historical chart review of patients whose dose of levetiracetam was raised to high dose levetiracetam \\>1500 mg/day (monotherapy) after a breakthrough seizure. No intervention was administered in the study.",
              "interventionNames": [
                "Drug: levetiracetam"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "lacosamide",
              "description": "Lacosamide maximum of 200 mg/day, to be titrated as follows:\n\n* Week 1: 50 mg twice a day\n* Beginning Week 2: 100 mg twice a day.",
              "armGroupLabels": [
                "Lacosamide + Low-Dose Levetiracetam"
              ],
              "otherNames": [
                "Vimpat"
              ]
            },
            {
              "type": "DRUG",
              "name": "levetiracetam",
              "description": "Low dose ≤1500 mg/day, High dose \\>1500 mg/day",
              "armGroupLabels": [
                "Control Group (High-Dose Levetiracetam)",
                "Lacosamide + Low-Dose Levetiracetam"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Percentage of Participants Achieving Six Month Seizure Freedom",
              "description": "Seizure freedom is defined as having no seizures and was evaluated in the 6 month period after receiving the drug.",
              "timeFrame": "6 Months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Number of Seizure-Free Days",
              "timeFrame": "6 Months"
            },
            {
              "measure": "Time to First Seizure After Therapeutic Dose is Reached",
              "description": "Time in days until the first seizure after the therapeutic dose is reached occurs.",
              "timeFrame": "6 Months"
            },
            {
              "measure": "Retention Rate",
              "description": "Retention rate is defined as the percentage of participants who remained on the study drug after study completion.",
              "timeFrame": "6 Months"
            },
            {
              "measure": "Number of Participants With Treatment-Emergent Adverse Events (TEAE)",
              "description": "An Adverse Event (AE) is defined as any untoward medical occurrence (side effect) in a clinical investigation participant administered a drug; it does not necessarily have to have a causal relationship with this treatment. A TEAE is defined as an adverse event that occurs after receiving the drug.",
              "timeFrame": "6 Months"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n1. Adults age 18 or older\n2. Determined to have had at least two partial seizures by an epilepsy specialist, or to have had a single partial seizure with clinical and/or laboratory evidence of a high seizure recurrence risk\n3. Monotherapy on levetiracetam less than or equal to 1500 mg/day for at least two weeks\n4. Breakthrough seizure while on stable dose (\\>5 days) of levetiracetam monotherapy regimen, not due to provocative factors (e.g. hypoglycemia, head trauma, missed medications)\n\nExclusion Criteria:\n\n1. Clinical suspicion of nonepileptic psychogenic seizures or idiopathic generalized epilepsy\n2. Pregnant, child-bearing age not using contraception, or breast feeding\n3. Medical contraindication to adding lacosamide\n4. History of antiepileptic drug (AED) polytherapy\n5. Presence of a vagus nerve stimulator\n6. Creatinine clearance of less than 50 mL/min\n7. Blood pressure instability: pulse \\<50 or \\>100, systolic blood pressure (SBP) \\<50 or \\>180, clinically significant electrocardiogram (EKG) abnormality\n8. History of significant drug rash or anaphylactic reaction with antiepileptic drug\n9. Patients with progressive lesions (e.g. brain tumors)",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
