              "name": "Placebo control",
              "description": "NaCl 0.9% sodium chloride in the same route and method of administration as experimental treatment",
              "armGroupLabels": [
                "Placebo control"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Number of days alive without delirium or coma",
              "timeFrame": "14 days after randomization"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Mortality in intensive care",
              "timeFrame": "At day 28"
            },
            {
              "measure": "Mortality in intensive care",
